use trinity_macros::trinity_test;use trinityal::{Tr2VertexDefinition,Tr2VertexDefinitionItem,VertexDataType,VertexUsageCode};
#[trinity_test(legacy="trinityal/tests/VertexDefinition.cpp::VertexDefinition::CanCompareVertexDefinitionItems",verification="kani")]fn can_compare_vertex_definition_items(){let a=Tr2VertexDefinitionItem{usage:VertexUsageCode::Position,usage_index:0,data_type:VertexDataType::FLOAT16_2,offset:0,stream:0,instance_step_rate:0};let b=Tr2VertexDefinitionItem{usage:VertexUsageCode::Texcoord,usage_index:0,data_type:VertexDataType::FLOAT16_2,offset:16,stream:0,instance_step_rate:0};assert_ne!(a,b);assert!(a<b);}
#[trinity_test(legacy="trinityal/tests/VertexDefinition.cpp::VertexDefinition::CanAddItemsToVertexDefinition",verification="kani")]fn can_add_items_to_vertex_definition(){let mut d=Tr2VertexDefinition::default();d.add_default(VertexDataType::FLOAT16_2,VertexUsageCode::Texcoord);d.add(VertexDataType::FLOAT32_3,VertexUsageCode::Position,2,1,1);d.add(VertexDataType::FLOAT32_3,VertexUsageCode::Position,0,1,0);d.add(VertexDataType::FLOAT32_1,VertexUsageCode::Normal,0,0,1);assert_eq!([0,0,12,4],[d.items[0].offset,d.items[1].offset,d.items[2].offset,d.items[3].offset]);}
